package com.timetravel.ui;
import com.timetravel.engine.*;import com.timetravel.model.*;import com.timetravel.service.*;import java.io.IOException;import java.util.*;
public final class ConsoleUI {
    private final Scanner in=new Scanner(System.in);private final SimulationService service=new SimulationService();private final SaveLoadService saves=new SaveLoadService();private final RandomEventEngine randomEvents=new RandomEventEngine();private final AchievementService achievements=new AchievementService();private boolean running=true;
    public void run(){banner();while(running){showHeader();menu();int choice=number("Select option: ",1,12);try{switch(choice){case 1->start();case 2->load();case 3->viewTimeline();case 4->travel();case 5->modify();case 6->branches();case 7->analyze();case 8->compare();case 9->consequences();case 10->save();case 11->statistics();case 12->running=false;}}catch(Exception e){System.out.println("\n[!] "+friendly(e));pause();}}System.out.println("\nThe chronal field is powered down. Safe travels.");}
    private void banner(){System.out.println("============================================================\n             TIME TRAVEL PARADOX SIMULATOR\n============================================================");}
    private void showHeader(){System.out.println("\n------------------------------------------------------------");if(serviceReady())System.out.printf(" Timeline %-7s | Year %d | Stability %.0f%% | Paradox %d | Energy %d%%%n",service.state().current().id(),service.state().current().currentYear(),service.state().current().stability(),service.state().current().paradox(),service.state().temporalEnergy());else System.out.println(" No active simulation - start a new simulation or load one.");System.out.println("------------------------------------------------------------");}
    private boolean serviceReady(){try{service.state();return true;}catch(IllegalStateException e){return false;}}
    private void menu(){String[] options={"Start New Simulation","Load Simulation","View Current Timeline","Time Travel","Modify Historical Event","View Timeline Branches","Analyze Paradox","Compare Timelines","View Consequences","Save Simulation","Simulation Statistics","Exit"};for(int i=0;i<options.length;i++)System.out.printf(" %2d. %s%n",i+1,options[i]);}
    private void start(){long seed=System.nanoTime();String value=ask("Seed (blank for random): ");if(!value.isBlank())try{seed=Long.parseLong(value);}catch(NumberFormatException e){System.out.println("Using a random seed.");}service.start(seed);System.out.println("New simulation created with seed "+seed+".");pause();}
    private void load()throws IOException,ClassNotFoundException{List<String> files=saves.list();if(files.isEmpty()){System.out.println("No saved simulations found.");pause();return;}files.forEach(System.out::println);String action=ask("Enter save name to load, or type DELETE <name> to remove one: ");if(action.toUpperCase(Locale.ROOT).startsWith("DELETE ")){String name=action.substring(7).trim();System.out.println(saves.delete(name)?"Save deleted.":"Save file not found.");}else{service.load(saves.load(action));System.out.println("Simulation loaded.");}pause();}
    private void viewTimeline(){requireState();Timeline t=service.state().current();section("CURRENT TIMELINE "+t.id());System.out.println("Parent: "+(t.parentId()==null?"Original":t.parentId())+" | Status: "+t.status()+" | Current year: "+t.currentYear());System.out.println("Events:");t.events().stream().sorted(Comparator.comparingInt(Event::year)).forEach(e->System.out.printf(" %4d  %-27s [%s]%s%n",e.year(),e.title(),e.category(),e.prevented()?" [PREVENTED]":""));System.out.println("Changes: "+t.changes().size()+" | Consequences: "+t.consequences().size());pause();}
    private void travel(){requireState();int year=number("Destination year (2000-2050): ",2000,2050);System.out.println(service.travel(year));Optional<RandomEventEngine.RandomOccurrence> occurrence=randomEvents.roll(service.state());occurrence.ifPresent(e->System.out.println("Random event: "+e.title()+" - "+e.description()+" (energy "+(e.energyChange()>=0?"+":"")+e.energyChange()+")"));achievements.update(service.state());pause();}
    private void modify(){requireState();Timeline t=service.state().current();List<Event> eligible=t.events().stream().filter(e->e.year()<=t.currentYear()).toList();if(eligible.isEmpty()){System.out.println("No historical events are available at this year. Travel forward first.");pause();return;}for(Event e:eligible)System.out.printf(" %s | %d | %s (importance %d)%n",e.id(),e.year(),e.title(),e.importance());String id=ask("Event ID: ");System.out.println("1 Prevent  2 Delay  3 Accelerate  4 Change outcome  5 Increase impact  6 Decrease impact");int choice=number("Modification: ",1,6);ModificationType type=ModificationType.values()[choice-1];int amount=(type==ModificationType.DELAY||type==ModificationType.ACCELERATE)?number("Years: ",1,50):0;List<Consequence> cs=service.modify(id,type,amount);System.out.println("Created branch "+service.state().current().id()+". Consequence chain:");cs.forEach(c->System.out.printf(" depth %d | %-12s %+d | %s%n",c.depth(),c.domain(),c.impact(),c.description()));System.out.println("Paradox is now "+service.state().current().paradox()+"/100; status "+service.state().current().status()+".");pause();}
    private void branches(){requireState();section("TIMELINE TREE");for(Timeline t:service.state().timelines().values()){int depth=0;String parent=t.parentId();while(parent!=null){depth++;Timeline p=service.state().timelines().get(parent);parent=p==null?null:p.parentId();}System.out.println("  "+"  ".repeat(depth)+(depth>0?"|-- ":"")+t.id()+(t.id().equals(service.state().currentTimelineId())?"  < current":"")+" ["+t.status()+"]");}String id=ask("Switch active timeline (ID, or blank to stay): ");if(!id.isBlank())service.state().currentTimelineId(id);pause();}
    private void analyze(){requireState();Timeline t=service.state().current();ParadoxEngine.Analysis a=service.analyze();section("PARADOX ANALYSIS");System.out.println("Timeline          : "+t.id()+"\nParadox score     : "+a.score()+"/100\nTimeline stability: "+a.stability()+"%\nButterfly effect  : "+a.butterfly()+"\nCausality risk    : "+a.causalityRisk()+"%\nTemporal energy   : "+a.energy()+"%\nStatus            : "+a.status());if(a.status()==TimelineStatus.UNSTABLE||a.status()==TimelineStatus.COLLAPSED){System.out.println("\nRecovery: 1 Undo latest branch  2 Return to parent  3 Stabilize (25 energy)  4 Continue");int c=number("Choice: ",1,4);if(c==1)service.undoLatest();else if(c==2&&t.parentId()!=null)service.state().currentTimelineId(t.parentId());else if(c==3)System.out.println(service.stabilize()?"Timeline stabilized.":"Stabilization unavailable; need 25 energy and an unstable timeline.");}pause();}
    private void compare(){requireState();String a=ask("First timeline ID: ");String b=ask("Second timeline ID: ");Timeline x=service.state().timelines().get(a),y=service.state().timelines().get(b);if(x==null||y==null)throw new IllegalArgumentException("Both timeline IDs must exist.");section("TIMELINE COMPARISON");System.out.printf("%-20s %-14s %-14s %-14s%n","Metric",x.id(),y.id(),"Difference");for(var e:SimulationService.compare(x,y).entrySet())System.out.printf("%-20s %-14d %-14d %+d%n",e.getKey(),x.metrics().getOrDefault(e.getKey(),(int)x.stability()),y.metrics().getOrDefault(e.getKey(),(int)y.stability()),e.getValue());pause();}
    private void consequences(){requireState();List<Consequence> list=service.state().current().consequences();section("CONSEQUENCES - "+service.state().current().id());if(list.isEmpty())System.out.println("No consequences recorded on this branch yet.");for(Consequence c:list)System.out.printf("Depth %d | %-12s %+d | %s%n",c.depth(),c.domain(),c.impact(),c.description());pause();}
    private void save()throws IOException{requireState();String name=ask("Save name: ");System.out.println("Saved to "+saves.save(service.state(),name));pause();}
    private void statistics(){requireState();PlayerStats s=service.state().stats();System.out.println("\nSIMULATION STATISTICS\nTimelines created   : "+service.state().timelines().size()+"\nTime travels        : "+s.timeTravels()+"\nEvents modified     : "+s.eventsModified()+"\nParadoxes created   : "+s.paradoxesCreated()+"\nTimelines collapsed : "+s.timelinesCollapsed()+"\nHighest paradox     : "+s.highestParadox()+"\nBest timeline       : "+service.state().timelines().values().stream().max(Comparator.comparingDouble(Timeline::stability)).map(Timeline::id).orElse("-")+"\nCurrent stability   : "+(int)service.state().current().stability()+"%");System.out.println("\nACHIEVEMENTS");achievements.all().forEach((n,d)->System.out.println((service.state().achievements().contains(n)?"[UNLOCKED] ":"[LOCKED]   ")+n+" - "+d));pause();}
    private void requireState(){if(!serviceReady())throw new IllegalStateException("Start a new simulation or load a save first.");}
    private int number(String prompt,int min,int max){while(true){String s=ask(prompt);try{int n=Integer.parseInt(s);if(n>=min&&n<=max)return n;}catch(NumberFormatException ignored){}System.out.println("Enter a whole number from "+min+" to "+max+".");}}
    private String ask(String prompt){System.out.print(prompt);return in.nextLine().trim();}private void section(String title){System.out.println("\n==================== "+title+" ====================");}private void pause(){System.out.println("\nPress Enter to continue...");if(in.hasNextLine())in.nextLine();}private String friendly(Exception e){return e.getMessage()==null?"The operation could not be completed.":e.getMessage();}
}

